def verify(w):
    # Pure, deterministic, fail-closed. No imports, no I/O, no floats.
    # The lemma L1 asserts: an exact rational certificate resolves all
    # residual signs with zero tolerance, valid under SHA 3b7fda95e07be822.
    if not isinstance(w, dict):
        return 'FAIL'
    if w.get('contract_sha256') != '3b7fda95e07be822':
        return 'FAIL'
    if w.get('tolerance') != 0:
        return 'FAIL'
    if w.get('certificate_on_file') is not True:
        return 'FAIL'
    rs = w.get('sign_resolutions')
    if not isinstance(rs, list) or len(rs) == 0:
        return 'FAIL'
    for r in rs:
        if not isinstance(r, dict):
            return 'FAIL'
        poly = r.get('polynomial')
        num = r.get('point_num')
        den = r.get('point_den')
        sign = r.get('sign')
        if not isinstance(poly, list) or not isinstance(num, int) or not isinstance(den, int):
            return 'FAIL'
        if den == 0 or sign not in (1, -1):
            return 'FAIL'
        # coefficients: list of (cnum, cden); rational point num/den
        # evaluate with exact integer arithmetic via common denominators
        acc_n = 0
        acc_d = 1
        xnum = num
        xden = den
        for coef in poly:
            if not (isinstance(coef, list) and len(coef) == 2):
                return 'FAIL'
            cn, cd = coef
            if not (isinstance(cn, int) and isinstance(cd, int)) or cd == 0:
                return 'FAIL'
            # term = (cn/cd) * (xnum/xden)^i, i = index
            i = poly.index(coef)  # deterministic list order
            tn = cn * (xnum ** i)
            td = cd * (xden ** i)
            if td == 0:
                return 'FAIL'
            # acc = acc + term  (cross-multiplied, exact)
            acc_n = acc_n * td + tn * acc_d
            acc_d = acc_d * td
            if acc_d == 0 or acc_n == 0 and acc_d == 0:
                return 'FAIL'
        if acc_n == 0:
            return 'FAIL'  # unresolved sign: polynomial vanishes at point
        actual = 1 if (acc_n > 0) == (acc_d > 0) else -1
        if actual != sign:
            return 'FAIL'
    return 'PASS'
